INSERT INTO publications (id, author, year_of_publication, doi, title) VALUES
  (1, 'Agomo', 2016, '10.1371/journal.pone.0146908', 'Assessment of Markers of Antimalarial Drug Resistance in Plasmodium falciparum Isolates from Pregnant Women in Lagos, Nigeria'),
  (2, 'Beshir', 2023, '10.1016/S1473-3099(22)00593-X', 'Prevalence of Plasmodium falciparum haplotypes associated with resistance to sulfadoxine–pyrimethamine and amodiaquine before and after upscaling of seasonal malaria chemoprevention in seven African countries: a genomic surveillance study'),
  (3, 'Dokunmu', 2019, '10.1186/s12936-019-2833-8', 'Asymptomatic malaria infections and Pfmdr1 mutations in an endemic area of Nigeria'),
  (4, 'Ibekpobaoku', 2024, '10.1186/s13104-024-06763-2', 'Sub-microscopic Plasmodium falciparum infections and multiple drug resistant single nucleotide polymorphic alleles in pregnant women from southwestern Nigeria'),
  (5, 'Adamu', 2020, '10.1186/s12936-020-03506-z', 'Plasmodium falciparum multidrug resistance gene‑1 polymorphisms in Northern Nigeria: implications for the continued use of artemether‑lumefantrine in the region'),
  (6, 'Fagbemi', 2020, '10.1016/j.meegid.2020.104503', 'Analysis of sulphadoxine–pyrimethamine resistance-associated mutations in Plasmodium falciparum isolates obtained from asymptomatic pregnant women in Ogun State, Southwest Nigeria'),
  (7, 'Figueroa-Romero', 2023, '10.1016/S2214-109X(23)00414-X', 'Prevalence of molecular markers of resistance to sulfadoxine–pyrimethamine before and after community delivery of intermittent preventive treatment of malaria in pregnancy in sub-Saharan Africa: a multi-country evaluation'),
  (8, 'Adegbola', 2023, '10.1186/s12936-023-04487-5', 'A snapshot of the prevalence of dihydropteroate synthase-431V mutation and other sulfadoxine-pyrimethamine resistance markers in Plasmodium falciparum isolates in Nigeria'),
  (9, 'Martín Ramírez', 2025, '10.1186/s41182-025-00732-6', 'Mutational profile of pfdhfr, pfdhps, pfmdr1, pfcrt and pfk13 genes of P. falciparum associated with resistance to different antimalarial drugs in Osun state, southwestern Nigeria'),
  (10, 'Abubakar', 2020, '10.3390/tropicalmed5020085', 'Identification of Mutations in Antimalarial Resistance Gene Kelch13 from Plasmodium falciparum Isolates in Kano, Nigeria'),
  (11, 'Ajogbasile', 2021, '10.1371/journal.pone.0264548', 'Molecular profiling of the artemisinin resistance Kelch 13 gene in Plasmodium falciparum from Nigeria'),
  (12, 'Idowu', 2019, '10.1186/s12936-019-2947-z', 'Rare mutations in Pfmdr1 gene of Plasmodium falciparum detected in clinical isolates from patients treated with anti-malarial drug in Nigeria'),
  (13, 'Ikegbunam', 2021, '10.1186/s12936-021-03968-9', 'Absence of Plasmodium falciparum artemisinin resistance gene mutations eleven years after the adoption of artemisinin‑based combination therapy in Nigeria'),
  (14, 'Oboh', 2018, NULL, NULL),
  (15, 'Amusan', 2025, '10.1371/journal.pone.0316479', 'Polymorphisms in Pfkelch13 domains before and after the introduction of artemisinin-based combination therapy in Southwest Nigeria'),
  (16, 'Zubair', 2024, '10.4178/epih.e2024087.E', 'Molecular Surveillance of Artemisinin Combination Therapy Resistance Markers in Kelch13 Gene of Plasmodium falciparum Isolates Collected From Yobe State Nigeria'),
  (17, 'Zhao', 2021, '10.3389/fcimb.2021.644576', 'Surveillance of Antimalarial Drug-Resistance Genes in Imported Plasmodium falciparum Isolates From Nigeria in Henan, China, 2012–2019'),
  (18, 'Kong', 2022, '10.1186/s12936-022-04398-x', 'Molecular surveillance of artemisinin resistance‑related Pfk13 and pfcrt polymorphisms in imported Plasmodium falciparum isolates reported in eastern China from 2015 to 2019'),
  (19, 'Wang', 2020, '10.1186/s12936-020-3140-0', 'Molecular surveillance of Pfcrt and k13 propeller polymorphisms of imported Plasmodium falciparum cases to Zhejiang Province, China between 2016 and 2018'),
  (20, 'Foguim', 2020, '10.1186/s12936-020-03281-x', 'Prevalence of mutations in the Plasmodium falciparum chloroquine resistance transporter, PfCRT, and association with ex vivo susceptibility to common anti‑malarial drugs against African Plasmodium falciparum isolates'),
  (21, 'Cheng', 2021, '10.1186/s12936-021-03737-8', 'Molecular surveillance of anti‑malarial resistance pfcrt, pfmdr1, and pfk13 polymorphisms in African Plasmodium falciparum imported parasites to Wuhan, China'),
  (22, 'Ajibaye', 2024, '10.3389/fcimb.2024.1366563', 'Detection of novel Plasmodium falciparum coronin gene mutations in a recrudescent ACT-treated patient in South-Western Nigeria'),
  (23, 'Wang', 2016, NULL, NULL),
  (24, 'Wang', 2022, '10.1128/spectrum.00528-22', 'Molecular Epidemiology of Drug Resistance Genes in Plasmodium falciparum Isolates Imported from Nigeria between 2016 and 2020: Continued Emergence of Fully Resistant Pfdhfr- Pfdhps Alleles'),
  (25, 'Wang', 2019, NULL, NULL),
  (26, 'Oboh', 2018, '10.1016/j.meegid.2018.10.007', 'Molecular epidemiology and evolution of drug-resistant genes in the malaria parasite Plasmodium falciparum in southwestern Nigeria'),
