INSERT INTO alert_rules (id, gene, mutation_pattern, antimalarial, resistance_level, reference_text) VALUES
  (1, 'hrp2', 'deletion', NULL, NULL, 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)'),
  (2, 'hrp3', 'deletion', NULL, NULL, 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)'),
  (3, 'crt', 'K76T', 'chloroquine', NULL, 'threshold based on own judgement, no WHO guideline is available'),
  (4, 'crt', '*', 'chloroquine', NULL, 'threshold based on own judgement, no WHO guideline is available'),
