INSERT INTO alert_levels (alert_rule_id, level_order, max_prevalence, classification, guideline, message, summary) VALUES
  (1, 1, 0.03, 'low', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp2 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is low.', 'No false-negative RDT results expected.'),
  (1, 2, 0.049, 'intermediate', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp2 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is increased and thereby false-negative results are likely.', 'False-negative RDT results are likely.'),
  (1, 3, 1.0, 'high', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp2 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is very high and actions according to https://www.who.int/publications/i/item/9789240101838 should be taken by the Malaria Elimination Program.', 'High probability for false-negative RDT results.'),
  (2, 1, 0.03, 'low', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp3 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is low.', 'No false-negative RDT results expected.'),
  (2, 2, 0.049, 'intermediate', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp3 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is increased and thereby false-negative results are likely.', 'False-negative RDT results are likely.'),
  (2, 3, 1.0, 'high', 'WHO guideline: if gene deletions have prevalence > 5% in a country, steps like switching to different RDT need to be taken (Response plan to pfhrp2 gene deletions, WHO, 2024)', 'Deletions of hrp3 can lead to false-negative results of HRP2-based RDTs. The prevalence of these deletions in this geographical area is very high and actions according to https://www.who.int/publications/i/item/9789240101838 should be taken by the Malaria Elimination Program.', 'High probability for false-negative RDT results.'),
  (3, 1, 1.0, 'high', 'threshold based on own judgement, no WHO guideline is available', 'This mutation is sufficent to confer full resistance to chloroquine, therefore the drug should no longer be used in this region.', 'Chloroquine sensitivity is reduced.'),
  (4, 1, 0.3, 'low', 'threshold based on own judgement, no WHO guideline is available', 'This mutation is present in a gene conferring resistance to chloroquine. The observed mutation is not a validated mutation for chloroquine resistance and present at low prevalence.', 'Chloroquine sensitivity is possibly reduced.'),
  (4, 2, 0.6, 'intermediate', 'threshold based on own judgement, no WHO guideline is available', 'This mutation is present in a gene conferring resistance to chloroquine. The observed mutation is not a validated mutation for chloroquine resistance but present at increased prevalence.', 'Chloroquine sensitivity is possibly reduced.'),
  (4, 3, 1.0, 'intermediate', 'threshold based on own judgement, no WHO guideline is available', 'This mutation is present in a gene conferring resistance to chloroquine. The observed mutation is not a validated mutation for chloroquine resistance but present atvery high prevalence.', 'Chloroquine sensitivity is possibly reduced.'),
  (5, 1, 0.3, 'low', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered partial resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is low in this geographical area.', 'Sulfdaxine/pyrimethamine resistance is low.'),
  (5, 2, 0.6, 'intermediate', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered partial resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is increased in this geographical area. SP used for seasonal malaria chemoprevention (SMC) and IPTp in pregnancy could be ineffective.', 'Sulfdaxine/pyrimethamine resistance expected.'),
  (5, 3, 1.0, 'intermediate', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered partial resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is increased in this geographical area. SP used for seasonal malaria chemoprevention (SMC) and IPTp in pregnancy could be ineffective.', 'High probability for partial resistance to sulfadoxine/pyrimethamine.'),
  (6, 1, 0.3, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is low in this geographical area, still the spread of these parasites can strongly influence the efficacy of sulfadoxine/pyrimethamine in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (6, 2, 0.6, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is increased in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (6, 3, 1.0, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered resistant to sulfadoxine-pyrimethamine. The prevalence of this haplotype is very high in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered very low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (7, 1, 0.3, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is low in this geographical area, still the spread of these parasites can strongly influence the efficacy of sulfadoxine/pyrimethamine in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (7, 2, 0.6, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is increased in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (7, 3, 1.0, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is very high in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (8, 1, 0.3, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is low in this geographical area, still the spread of these parasites can strongly influence the efficacy of sulfadoxine/pyrimethamine in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (8, 2, 0.6, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is increased in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (8, 3, 1.0, 'high', 'threshold based on own judgement, WHO states SP can still be effective in SMC and IPTp even if high prevalence of mutations', 'Parasites with this haplotype combination are considered "super resistant" to sulfadoxine-pyrimethamine. The prevalence of this haplotype is very high in this geographical area, therefore the efficacy of sulfadoxine/pyrimethamine is considered low in this geographical area.', 'Full resistance to sulfadoxine/pyrimethamine.'),
  (9, 1, 0.3, 'low', 'threshold based on own judgement, no WHO guideline is available', 'There is low resistance level in this region. So drug is still expected to active.', 'Piperaquine is still expected to work.'),
  (9, 2, 0.6, 'intermediate', 'threshold based on own judgement, no WHO guideline is available', 'Resistance to piperaquine is increasing in this region, drug sensitivity is expected to be reduced. The use of other artemisinin partner drugs are therefore recommended.', 'Reduced sensitivity to piperaquine is expected.'),
  (9, 3, 1.0, 'high', 'threshold based on own judgement, no WHO guideline is available', 'Due to high level of resistance in this region, piperaquine is no longer suitable and its use (especially as artemisinin partner drug) should be stopped.', 'Reduced sensitivity to piperaquine is expected.'),
  (10, 1, 1.0, 'high', 'https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance', 'This molecular marker is a validated mutation leading to artemsisin partial resistance (WHO, 2025).', 'Reduced sensitivity to artemisinin is expected.'),
