  (23, 1, 0.3, 'low', 'https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance', 'This molecular marker is a validated mutation leading to artemsisin partial resistance (WHO, 2025).', 'Reduced sensitivity to artemisinin is likely.'),
  (23, 2, 0.6, 'intermediate', 'threshold based on own judgement, no WHO guideline is available, https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance', 'This molecular marker is a candidate mutation for artemsisin partial resistance as classified by WHO. It is present at increased prevalence in this region. Artemisinin might no longer be active.', 'Reduced sensitivity to artemisinin is likely.'),
  (23, 3, 1.0, 'high', 'threshold based on own judgement, no WHO guideline is available, https://www.who.int/news-room/questions-and-answers/item/artemisinin-resistance', 'This molecular marker is a candidate mutation for artemsisin partial resistance as classified by WHO. It is present at very high prevalence in this region. There is a high chance that artemisinin is not active any more in this geographical region.', 'Reduced sensitivity to artemisinin is likely.'),
